from __future__ import annotations
import math
def calculate(sim):
    completed=sim.queue.completed; all_tasks=completed+sim.queue.failed+list(sim.queue.pending.values()); n=len(all_tasks); done=len(completed)
    lat=[r.completed_at_s-r.task.created_at_s for r in completed if r.completed_at_s is not None]
    critical=[r for r in all_tasks if r.task.is_critical()]; critical_done=[r for r in completed if r.task.is_critical()]
    return {"tasks_total":n,"tasks_completed":done,"task_completion_rate":done/n if n else 0.,"critical_task_completion_rate":len(critical_done)/len(critical) if critical else 0.,"deadline_miss_rate":sum((r.completed_at_s or sim.satellite.time_s)>r.task.deadline_s for r in all_tasks)/n if n else 0.,"average_latency_s":sum(lat)/len(lat) if lat else 0.,"p95_latency_s":sorted(lat)[max(0,math.ceil(.95*len(lat))-1)] if lat else 0.,"total_energy_consumed_j":sim.energy_consumed_j,"energy_per_completed_task_j":sim.energy_consumed_j/done if done else 0.,"total_transmitted_data_mb":sum(r.payload_mb or 0 for r in completed),"peak_storage_utilization":sim.peak_storage_mb/sim.satellite.storage_total_mb,"average_compute_utilization":sum(1 for x in sim.history if x["action"]=="PROCESS")/len(sim.history) if sim.history else 0.,"average_information_age_s":sum(sim.satellite.time_s-r.task.created_at_s for r in completed)/done if done else 0.,"total_mission_value_completed":sum(r.task.value_at(r.completed_at_s or sim.satellite.time_s) for r in completed),"mission_efficiency":sum(r.task.value_at(r.completed_at_s or sim.satellite.time_s) for r in completed)/sim.energy_consumed_j if sim.energy_consumed_j else 0.}
